        LinkerParam::Args(vec!["-static".to_string(), "-nostartfiles".to_string()])
    );
}

#[test]
fn load_ex_x2_spec() {
    let spec = load_spec(&app_tspec("ex-x2")).unwrap();

    assert_eq!(spec.cargo, CargoConfig::default());
    assert_eq!(spec.rustc, RustcConfig::default());
